function TodoRow({
  item,
  compact,
  animate,
  onRetry,
}: {
  item: TodoItem
  compact: boolean
  animate: boolean
  onRetry?: () => void
}) {
  const { status } = item
  const active = status === "in-progress"
  const struck = status === "done" || status === "skipped" || status === "cancelled"
  return (
    <li
      data-slot="todo-item"
      data-task-status={status}
      className={cn(
        "flex min-w-0 items-start gap-2.5",
        compact ? "py-1" : "px-1 py-1.5",
        animate && "ease-(--chatcn-ease-out-soft) transition-opacity duration-200 starting:opacity-0",
      )}
    >
      {/* The glyph centers on the first line of text, whatever the line height. */}
      <span className="flex h-5 shrink-0 items-center">
        <TaskStatusGlyph status={status} />
      </span>
      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
        <span
          className={cn(
            "text-pretty",
            "ease-(--chatcn-ease-standard) transition-[color,text-decoration-color] duration-150 motion-reduce:transition-none",
            active ? "text-(color:--chatcn-fg) font-medium" : "text-(color:--chatcn-fg)",
            struck && "text-(color:--chatcn-fg-subtle) decoration-(color:--chatcn-fg-faint) line-through decoration-1",
            status === "pending" && "text-(color:--chatcn-fg-muted)",
          )}
        >
          <span className="sr-only">{TASK_STATUS_TEXT[status]}: </span>
          {active && item.activeTitle ? item.activeTitle : item.title}
        </span>
        {item.detail ? (
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) text-pretty">{item.detail}</span>
        ) : null}
