/* -------------------------------------------------------------------------------------------------
 * TodoList
 * -----------------------------------------------------------------------------------------------*/

/**
 * The agent's checklist. A ring waits, a spinner works, an ink disc with a drawn check is done.
 * The count reads "3 of 7" and updates in place; screen readers hear one sentence per change.
 */
export function TodoList({
  items,
  title = "Todos",
  variant = "card",
  loading = false,
  collapsible = false,
  open: openProp,
  defaultOpen = true,
  onOpenChange,
  empty = "The agent's checklist shows up here once it plans the work.",
  onRetryItem,
  className,
  ...props
}: TodoListProps) {
  const compact = variant === "compact"
  const initial = useInitialIds(items.map((i) => i.id))
  const announcement = useTodoAnnouncement(items)
  const [openState, setOpenState] = React.useState(defaultOpen)
  const open = collapsible ? (openProp ?? openState) : true
  const setOpen = (next: boolean) => {
    if (openProp === undefined) setOpenState(next)
    onOpenChange?.(next)
  }

  const current =
    items.find((i) => i.status === "in-progress") ??
    items.find((i) => i.status === "blocked") ??
    items.find((i) => i.status === "pending")
  const allDone = items.length > 0 && items.every((i) => isTaskSettled(i.status))

  const list =
    items.length === 0 && !loading ? (
      <p className={cn("text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle)", compact ? "py-1" : "px-1 py-1.5")}>
        {empty}
      </p>
    ) : (
      <ul aria-label={typeof title === "string" ? title : "Todos"} className="flex flex-col">
        {items.map((item) => (
          <TodoRow
            key={item.id}
            item={item}
            compact={compact}
            animate={!initial.has(item.id)}
            onRetry={onRetryItem ? () => onRetryItem(item.id) : undefined}
          />
        ))}
        {loading ? (
          <li className={cn("flex items-center gap-2.5", compact ? "py-1" : "px-1 py-1.5")}>
            <span className="size-4 shrink-0" />
            <ShimmerText className="text-[0.8125rem]/[1.25rem]">Writing todos</ShimmerText>
          </li>
        ) : null}
      </ul>
    )

  /** What the folded header shows: the todo in progress, else the title. */
  const summary =
    collapsible && !open && current ? (
      <span className="flex min-w-0 items-center gap-2.5">
        <TaskStatusGlyph status={current.status} />
        <span key={current.id} className="text-(color:--chatcn-fg) truncate font-medium">
          {current.status === "in-progress" && current.activeTitle
            ? current.activeTitle
            : current.title}
        </span>
      </span>
    ) : (
      <span className="flex min-w-0 items-center gap-2.5">
        <ListChecksIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-4 shrink-0" />
        <span className="text-(color:--chatcn-fg) truncate font-medium">
          {allDone && items.length > 0 ? "All done" : title}
        </span>
      </span>
    )

  const headerInner = (
    <>
      <span className="min-w-0 flex-1">{summary}</span>
      {items.length > 0 ? <TodoCount items={items} /> : null}
      {collapsible ? (
        <ChevronDownIcon
          aria-hidden="true"
          className={cn(
            "text-(color:--chatcn-fg-subtle) ease-(--chatcn-ease-out) size-4 shrink-0 transition-transform duration-200 motion-reduce:transition-none",
            open ? "rotate-180" : "",
          )}
        />
      ) : null}
    </>
  )

  const headerClass = cn(
    "flex w-full min-w-0 items-center gap-2.5 text-start",
    compact ? "h-7" : "h-10 px-4",
  )

  return (
    <div
      data-slot="todo-list"
      data-variant={variant}
      className={cn(
        "text-(color:--chatcn-fg) flex min-w-0 flex-col",
        compact ? "text-[0.8125rem]/[1.25rem]" : "text-[0.875rem]/[1.25rem] tracking-[-0.003em]",
        !compact && "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) overflow-hidden",
        className,
      )}
      {...props}
    >
      <Collapsible.Root open={open} onOpenChange={setOpen} disabled={!collapsible} render={<div />}>
        {collapsible ? (
          <Collapsible.Trigger
            className={cn(
              headerClass,
              "ease-(--chatcn-ease-standard) transition-colors duration-150 outline-none select-none",
              "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:-outline-offset-2",
              compact
                ? "rounded-(--chatcn-radius-sm) hover:bg-(color:--chatcn-fill-hover) -mx-1 w-[calc(100%+0.5rem)] px-1"
                : "hover:bg-(color:--chatcn-alpha-100)",
              "pointer-coarse:min-h-11",
            )}
          >
            {headerInner}
          </Collapsible.Trigger>
        ) : (
          <div className={headerClass}>{headerInner}</div>
        )}
        <div className={cn(compact ? "pb-1.5" : "px-4 pb-2")}>
          <TodoProgress items={items} />
        </div>
        <Collapsible.Panel
          className={cn(
            "h-(--collapsible-panel-height) overflow-hidden",
            "ease-(--chatcn-ease-out) transition-[height,opacity] duration-200 motion-reduce:transition-none",
            "data-[ending-style]:h-0 data-[ending-style]:opacity-0 data-[ending-style]:duration-150",
            "data-[starting-style]:h-0 data-[starting-style]:opacity-0",
          )}
        >
          <div className={cn(compact ? "pt-0.5" : "px-3 pb-2.5")}>{list}</div>
        </Collapsible.Panel>
      </Collapsible.Root>
      <span aria-live="polite" className="sr-only">
        {announcement}
      </span>
    </div>
  )
}

export default TodoList

