]

/** A todo finishes about every 1.4 s; the list restarts after a pause. */
function TodoListDemo() {
  const [step, setStep] = React.useState(0)
  React.useEffect(() => {
    const id = window.setTimeout(
      () => setStep((s) => (s >= ITEMS.length * 2 + 3 ? 0 : s + 1)),
      step === 0 ? 900 : step % 2 === 1 ? 1100 : 300,
    )
    return () => window.clearTimeout(id)
  }, [step])

  // Odd steps start a todo, even steps finish it.
  const items: TodoItem[] = ITEMS.map((item, i) => {
    let status: TaskStatus = "pending"
    if (step >= i * 2 + 2) status = "done"
    else if (step >= i * 2 + 1) status = "in-progress"
    return { ...item, status }
  })

  return <TodoList items={items} className="w-full max-w-md" />
}

